def check(raw, record):
    if (len(raw)>=100000 or len(raw)!=record["bytes"]
            or hashlib.sha256(raw).hexdigest()!=record["sha256"]):
        raise ValueError("Complete declared text differs: "+record["name"])
    return raw.decode("utf-8")


def replace_exact(text, patch, reverse=False):
    old=patch["new"] if reverse else patch["old"]
    new=patch["old"] if reverse else patch["new"]
    if text.count(old)!=patch["count"]:
        raise ValueError("The exact source occurrence count changed")
    return text.replace(old,new)


def remap(value, old, new):
    if isinstance(value,str):
        return value.replace(old,new)
    if isinstance(value,list):
        return [remap(v,old,new) for v in value]
    if isinstance(value,dict):
        return {k.replace(old,new):remap(v,old,new) for k,v in value.items()}
    return value


def make_plan(original, spec):
    value=json.loads(original)
    before=json.loads(original)
    value["schema"]=value["schema"].replace("N4096-","N4096-base-bound-")
    for item in DATA["runtimes"]:
        del value["complete_source_sha256"][item["parent"]["name"]]
        value["complete_source_sha256"][item["output"]["name"]]=item["output"]["sha256"]
    provenance=json.loads(DATA["provenance"]["source"])
    if value["complete_source_sha256"]!=provenance["complete_source_sha256"]:
        raise ValueError("The entire original source table was not preserved with exactly three replacements")
    value["scope"]+=" This source-specific successor corrects only the actual normal constructor's expected base schema; all mathematical bodies and the complete 128 source roles are unchanged. The earlier failed output directory remains untouched."
    value["steps"]=remap(value["steps"],spec["old_output_directory"],spec["new_output_directory"])
    for step in value["steps"]:
        for item in DATA["runtimes"]:
            if step["script"]==item["parent"]["path"]:
                step["script"]=item["output"]["path"]
    value["source_only_status"]=spec["source_only_status"]
    value["complete_current_parameter_parent"]=spec["parent"]
    value["actual_constructor_repair"]=spec["actual_constructor_repair"]
    del value["complete_source_sha256"]
    value["complete_source_sha256_record"]=dict(DATA["provenance"]["record"],
        field="complete_source_sha256",all_complete_source_values_preserved=True)
    backwards=remap(value["steps"],spec["new_output_directory"],spec["old_output_directory"])
    for step in backwards:
        for item in DATA["runtimes"]:
            if step["script"]==item["output"]["path"]:
                step["script"]=item["parent"]["path"]
    if backwards!=before["steps"]:
        raise ValueError("Every original argv, selector, output and progress object must be retained")
    return json.dumps(value,ensure_ascii=False,separators=(",",":"),allow_nan=False)+"\n"


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source-directory",type=Path,required=True)
    parser.add_argument("--parameter-directory",type=Path,required=True)
    parser.add_argument("--output-source-directory",type=Path,required=True)
    parser.add_argument("--output-parameter-directory",type=Path,required=True)
    args=parser.parse_args()
    sources=args.source_directory.resolve()
    parameters=args.parameter_directory.resolve()
    out_sources=args.output_source_directory.resolve()
    out_parameters=args.output_parameter_directory.resolve()
    if sources==out_sources or parameters==out_parameters:
        raise ValueError("Keep complete original files and independent output paths separate")
    originals=[]
    outputs=[]
    for item in DATA["runtimes"]:
        path=sources/item["parent"]["name"]
        original=check(path.read_bytes(),item["parent"])
        result=original
        for patch in item["patches"]:
            result=replace_exact(result,patch)
        raw=result.encode("utf-8")
        check(raw,item["output"])
        reverse=result
        for patch in reversed(item["patches"]):
            reverse=replace_exact(reverse,patch,reverse=True)
        if reverse!=original:
            raise ValueError("The whole original runtime was not recovered")
        originals.append((path,item["parent"]))
        outputs.append((out_sources/item["output"]["name"],raw,item["output"]))
    p=DATA["provenance"]
    raw=p["source"].encode("utf-8")
    check(raw,p["record"])
    outputs.append((out_parameters/p["record"]["name"],raw,p["record"]))
    for spec in DATA["plans"]:
        path=parameters/spec["parent"]["name"]
        original=check(path.read_bytes(),spec["parent"])
        raw=make_plan(original,spec).encode("utf-8")
        check(raw,spec["output"])
        originals.append((path,spec["parent"]))
        outputs.append((out_parameters/spec["output"]["name"],raw,spec["output"]))
    for path,raw,record in outputs:
        if path.exists() and path.read_bytes()!=raw:
            raise ValueError("Do not overwrite a different source or complete parameter file")
    for path,raw,record in outputs:
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_bytes(raw)
        check(path.read_bytes(),record)
    for path,record in originals:
        check(path.read_bytes(),record)
    print(json.dumps(dict(schema=DATA["schema"],complete_output_records=[r for _,_,r in outputs],
        original_complete_steps_retained=True,scientific_execution=False,
        additional_scientific_gate=False),sort_keys=True))


if __name__=="__main__":
    main()
